RATES = {"USD": 1.0, "EUR": 1.1, "GBP": 1.27}


def enrich(records):
    out = []
    for r in records:
        e = dict(r)
        e["usd"] = round(r["amount"] * RATES[r["currency"]], 2)
        out.append(e)
    return out

sources.pipeline/report.py:
def summarize(enriched):
    total = round(sum(e["usd"] for e in enriched), 2)
    return {"count": len(enriched), "total_usd": total}

